 34	public class Api {
 35	    private static final Logger logger = LoggerFactory.getLogger(Api.class);
 36	    private static final Gson gson = createGson();
 37	
 38	    private static Gson createGson() {
 39	        GsonBuilder builder = new GsonBuilder();
 40	        builder.registerTypeAdapter(BigDecimal.class, new JsonSerializer<BigDecimal>() {
 41	            @Override
 42	            public JsonElement serialize(BigDecimal src, Type typeOfSrc,
 43	                                         JsonSerializationContext context) {
 44	                return new JsonPrimitive(src.setScale(2, java.math.RoundingMode.HALF_EVEN));
 45	            }
 46	        });
 47	        return builder.create();
 48	    }
