 50	    public static void register(Javalin app) {
 51	        app.get("/rooms", Api::getRooms);
 52	
 53	        app.post("/reservations", Api::createReservation);
 54	        app.get("/reservations/{id}", Api::getReservation);
 55	        app.post("/reservations/{id}/confirmation", Api::confirmReservation);
 56	        app.post("/reservations/{id}/check-in", Api::checkIn);
 57	        app.post("/reservations/{id}/check-out", Api::checkOut);
 58	        app.post("/reservations/{id}/cancellation", Api::cancelReservation);
 59	        app.get("/reservations/{id}/document", Api::getDocument);
 60	
 61	        app.get("/messages", Api::getMessages);
 62	
 63	        app.get("/reports/occupancy", Api::getOccupancyReport);
 64	        app.get("/reports/revenue", Api::getRevenueReport);
 65	        app.get("/reports/tourism-tax", Api::getTourismTaxReport);
 66	        app.get("/reports/rate-plans", Api::getRatePlanReport);
 67	
 68	        app.exception(ApiException.class, Api::handleApiException);
 69	        app.exception(IllegalArgumentException.class, Api::handleIllegalArgumentException);
 70	        app.exception(Exception.class, Api::handleGenericException);
 71	    }
