 78	    private static void createReservation(Context ctx) {
 79	        try {
 80	            Map<String, Object> body = gson.fromJson(ctx.body(), Map.class);
 81	
 82	            if (body == null || !body.containsKey("roomNumber") || !body.containsKey("guestName") ||
 83	                !body.containsKey("guestEmail") || !body.containsKey("guestCpf") ||
 84	                !body.containsKey("checkIn") || !body.containsKey("checkOut") ||
 85	                !body.containsKey("guests") || !body.containsKey("ratePlan")) {
 86	                throw new ApiException(400, "INVALID_REQUEST", "Missing required fields");
 87	            }
 88	
 89	            ReservationService.CreateReservationRequest req = new ReservationService.CreateReservationRequest();
 90	            req.roomNumber = ((Number) body.get("roomNumber")).intValue();
 91	            req.guestName = (String) body.get("guestName");
 92	            req.guestEmail = (String) body.get("guestEmail");
 93	            req.guestCpf = (String) body.get("guestCpf");
 94	            req.checkIn = DateUtils.parseDate((String) body.get("checkIn"));
 95	            req.checkOut = DateUtils.parseDate((String) body.get("checkOut"));
 96	            req.guests = ((Number) body.get("guests")).intValue();
 97	            req.ratePlan = (String) body.get("ratePlan");
 98	
 99	            Reservation reservation = ReservationService.createReservation(req);
100	            ctx.status(HttpStatus.CREATED);
101	            ctx.json(toJson(reservation));
102	        } catch (IllegalArgumentException e) {
103	            throw new ApiException(400, "INVALID_REQUEST", e.getMessage());
104	        }
105	    }
