107	    private static void getReservation(Context ctx) {
108	        int id = Integer.parseInt(ctx.pathParam("id"));
109	        Reservation reservation = com.pousada.repositories.ReservationRepository.findById(id);
110	        if (reservation == null) {
111	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
112	        }
113	        ctx.json(toJson(reservation));
114	    }
