116	    private static void confirmReservation(Context ctx) {
117	        try {
118	            int id = Integer.parseInt(ctx.pathParam("id"));
119	            Map<String, Object> body = gson.fromJson(ctx.body(), Map.class);
120	
121	            if (body == null || !body.containsKey("amountPaid")) {
122	                throw new ApiException(400, "INVALID_REQUEST", "Missing amountPaid field");
123	            }
124	
125	            BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
126	            Reservation reservation = ReservationService.confirmReservation(id, amountPaid);
