152	    private static void getDocument(Context ctx) {
153	        int id = Integer.parseInt(ctx.pathParam("id"));
154	        Reservation reservation = com.pousada.repositories.ReservationRepository.findById(id);
155	        if (reservation == null) {
156	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
157	        }
158	
159	        if (!("CONFIRMED".equals(reservation.getStatus()) ||
160	              "CHECKED_IN".equals(reservation.getStatus()) ||
161	              "CHECKED_OUT".equals(reservation.getStatus()))) {
162	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Receipt only available for paid reservations");
163	        }
164	
165	        Receipt receipt = ReceiptService.generateReceipt(reservation);
166	        ctx.json(toReceiptJson(receipt));
167	    }
