269	    private static Map<String, Object> toJson(Reservation res) {
270	        Map<String, Object> map = new HashMap<>();
271	        map.put("id", res.getId());
272	        map.put("roomNumber", res.getRoomNumber());
273	        map.put("guestName", res.getGuestName());
274	        map.put("guestEmail", res.getGuestEmail());
275	        map.put("guestCpf", res.getGuestCpf());
276	        map.put("checkIn", DateUtils.formatIsoDate(res.getCheckIn()));
277	        map.put("checkOut", DateUtils.formatIsoDate(res.getCheckOut()));
278	        map.put("guests", res.getGuests());
279	        map.put("ratePlan", res.getRatePlan());
280	        map.put("nights", res.getNights());
281	        map.put("subtotal", res.getSubtotal());
282	        map.put("discount", res.getDiscount());
283	        map.put("total", res.getTotal());
284	        map.put("status", res.getStatus());
285	        map.put("amountPaid", res.getAmountPaid());
286	        map.put("refund", res.getRefund());
287	        return map;
288	    }
