291	        Map<String, Object> map = new HashMap<>();
292	        map.put("title", receipt.getTitle());
293	        map.put("reservationId", receipt.getReservationId());
294	        map.put("guestName", receipt.getGuestName());
295	        map.put("guestCpf", receipt.getGuestCpf());
296	        map.put("roomNumber", receipt.getRoomNumber());
297	        map.put("roomType", receipt.getRoomType());
298	        map.put("checkIn", DateUtils.formatIsoDate(receipt.getCheckIn()));
299	        map.put("checkOut", DateUtils.formatIsoDate(receipt.getCheckOut()));
300	        map.put("nights", receipt.getNights());
301	        map.put("subtotal", receipt.getSubtotal());
302	        map.put("discount", receipt.getDiscount());
303	        map.put("total", receipt.getTotal());
