343	import com.zaxxer.hikari.HikariConfig;
344	import com.zaxxer.hikari.HikariDataSource;
345	import org.slf4j.Logger;
346	import org.slf4j.LoggerFactory;
347	
348	import java.sql.Connection;
349	import java.sql.SQLException;
350	import java.sql.Statement;
351	
352	public class Database {
353	    private static final Logger logger = LoggerFactory.getLogger(Database.class);
354	    private static HikariDataSource dataSource;
355	
356	    public static void init() throws SQLException {
357	        String dbUrl = System.getenv("DB_URL");
358	        String dbUser = System.getenv("DB_USER");
359	        String dbPassword = System.getenv("DB_PASSWORD");
360	
361	        if (dbUrl == null || dbUser == null || dbPassword == null) {
362	            throw new IllegalArgumentException("Database environment variables not set");
363	        }
364	
365	        HikariConfig config = new HikariConfig();
366	        config.setJdbcUrl(dbUrl);
367	        config.setUsername(dbUser);
368	        config.setPassword(dbPassword);
369	        config.setMaximumPoolSize(10);
370	
371	        dataSource = new HikariDataSource(config);
372	
373	        createSchema();
374	        logger.info("Database schema created/verified");
375	    }
376	
377	    private static void createSchema() throws SQLException {
378	        try (Connection conn = dataSource.getConnection();
379	             Statement stmt = conn.createStatement()) {
380	
381	            stmt.execute("""
382	                CREATE TABLE IF NOT EXISTS rooms (
383	                    number INTEGER PRIMARY KEY,
384	                    type VARCHAR(20) NOT NULL,
385	                    capacity INTEGER NOT NULL,
386	                    nightly_rate DECIMAL(10, 2) NOT NULL
387	                )
388	                """);
389	
390	            stmt.execute("""
391	                CREATE TABLE IF NOT EXISTS reservations (
392	                    id SERIAL PRIMARY KEY,
393	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
394	                    guest_name VARCHAR(255) NOT NULL,
395	                    guest_email VARCHAR(255) NOT NULL,
396	                    guest_cpf VARCHAR(20) NOT NULL,
397	                    check_in DATE NOT NULL,
398	                    check_out DATE NOT NULL,
399	                    guests INTEGER NOT NULL,
400	                    rate_plan VARCHAR(20) NOT NULL,
401	                    nights INTEGER NOT NULL,
402	                    subtotal DECIMAL(10, 2) NOT NULL,
403	                    discount DECIMAL(10, 2) NOT NULL,
404	                    total DECIMAL(10, 2) NOT NULL,
405	                    status VARCHAR(20) NOT NULL,
406	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
407	                    refund DECIMAL(10, 2),
408	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
409	                )
410	                """);
411	
412	            stmt.execute("""
413	                CREATE TABLE IF NOT EXISTS messages (
414	                    id SERIAL PRIMARY KEY,
415	                    channel VARCHAR(50) NOT NULL,
416	                    recipient VARCHAR(255) NOT NULL,
417	                    subject VARCHAR(255) NOT NULL,
418	                    body TEXT NOT NULL,
419	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
420	                )
421	                """);
422	
423	            stmt.execute("""
424	                CREATE INDEX IF NOT EXISTS idx_reservations_room_dates
425	                ON reservations(room_number, check_in, check_out, status)
426	                """);
427	
428	            stmt.execute("""
429	                CREATE INDEX IF NOT EXISTS idx_reservations_check_in
430	                ON reservations(check_in)
431	                """);
432	        }
433	
434	        insertInitialRooms();
435	    }
436	
437	    private static void insertInitialRooms() throws SQLException {
438	        try (Connection conn = dataSource.getConnection();
439	             Statement stmt = conn.createStatement()) {
440	
441	            stmt.execute("DELETE FROM rooms");
442	
443	            stmt.execute("""
444	                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
445	                (101, 'STANDARD', 2, 249.90),
446	                (102, 'STANDARD', 2, 249.90),
447	                (201, 'DELUXE', 3, 389.90),
448	                (202, 'DELUXE', 3, 389.90),
449	                (301, 'SUITE', 4, 579.90)
450	                """);
451	        }
452	    }
453	
454	    public static HikariDataSource getDataSource() {
455	        return dataSource;
456	    }
457	}

