    15	public class ReceiptService {
    16	    private static final DecimalFormat MONEY_FORMAT = createMoneyFormat();
    17	
    18	    private static DecimalFormat createMoneyFormat() {
    19	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
    20	        DecimalFormat format = new DecimalFormat("#,##0.00", symbols);
    21	        return format;
    22	    }
    23	
    24	    private static String formatMoney(BigDecimal value) {
    25	        return "R$ " + MONEY_FORMAT.format(value);
    26	    }
    27	
    28	    public static Receipt generateReceipt(Reservation reservation) {
    29	        Room room = RoomRepository.findByNumber(reservation.getRoomNumber());
    30	
    31	        return new Receipt(
    32	            reservation.getId(),
    33	            reservation.getGuestName(),
    34	            reservation.getGuestCpf(),
    35	            reservation.getRoomNumber(),
    36	            room.getType(),
    37	            reservation.getCheckIn(),
    38	            reservation.getCheckOut(),
    39	            reservation.getNights(),
    40	            reservation.getSubtotal(),
    41	            reservation.getDiscount(),
    42	            reservation.getTotal()
    43	        );
    44	    }
    45	
    46	    public static String formatReceipt(Receipt receipt) {
    47	        StringBuilder sb = new StringBuilder();
    48	
    49	        sb.append("Comprovante de reserva nº ").append(receipt.getReservationId()).append("\n");
    50	        sb.append("Hóspede: ").append(receipt.getGuestName())
    51	            .append(" (CPF ").append(receipt.getGuestCpf()).append(")\n");
    52	        sb.append("Quarto: ").append(receipt.getRoomNumber())
    53	            .append(" (").append(receipt.getRoomType()).append(")\n");
    54	
    55	        sb.append("Entrada: ").append(DateUtils.formatDate(receipt.getCheckIn()))
    56	            .append(" | Saída: ").append(DateUtils.formatDate(receipt.getCheckOut()))
    57	            .append(" | ");
    58	
    59	        if (receipt.getNights() == 1) {
    60	            sb.append("1 diária");
    61	        } else {
    62	            sb.append(receipt.getNights()).append(" diárias");
    63	        }
    64	        sb.append("\n");
    65	
    66	        sb.append("Diárias: ").append(formatMoney(receipt.getSubtotal())).append("\n");
    67	
    68	        if (receipt.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
    69	            sb.append("Desconto: ").append(formatMoney(receipt.getDiscount())).append("\n");
    70	        }
    71	
    72	        sb.append("Total: ").append(formatMoney(receipt.getTotal()));
    73	
    74	        return sb.toString();
    75	    }
