    77	    public static void sendConfirmationEmail(Reservation reservation) {
    78	        Receipt receipt = generateReceipt(reservation);
    79	        String receiptText = formatReceipt(receipt);
    80	
    81	        String subject = "Reserva confirmada - Pousada Maré Alta";
    82	        String body = "Olá, " + reservation.getGuestName() + "!\n\n" +
    83	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
    84	            receiptText + "\n\n" +
    85	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
    86	            "Até breve!";
    87	
    88	        MessageRepository.create("EMAIL", reservation.getGuestEmail(), subject, body);
    89	    }
