    18	    private static final BigDecimal TOURISM_TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
    19	
    20	    private static DecimalFormat createMoneyFormat() {
    21	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
