   114	    public static String generateRatePlanReport(YearMonth month) {
   115	        List<Reservation> reservations = ReservationRepository.findForRevenue(month);
   116	
   117	        Map<String, BigDecimal> planAmounts = new LinkedHashMap<>();
   118	        Map<String, Integer> planCounts = new LinkedHashMap<>();
   119	
   120	        planAmounts.put("STANDARD", BigDecimal.ZERO);
   121	        planAmounts.put("NON_REFUNDABLE", BigDecimal.ZERO);
