   125	        for (Reservation res : reservations) {
   126	            BigDecimal amount = res.getAmountPaid();
   127	            if (res.getRefund() != null) {
   128	                amount = amount.subtract(res.getRefund());
   129	            }
   130	
   131	            String plan = res.getRatePlan();
   132	            planAmounts.put(plan, planAmounts.getOrDefault(plan, BigDecimal.ZERO).add(amount));
   133	            planCounts.put(plan, planCounts.getOrDefault(plan, 0) + 1);
   134	        }
   135	
   136	        StringBuilder csv = new StringBuilder();
   137	        csv.append("Pousada Maré Alta,rate-plans,").append(month).append("\n");
   138	        csv.append("rate_plan,reservations,amount\n");
   139	
   140	        BigDecimal totalAmount = BigDecimal.ZERO;
   141	        int totalCount = 0;
   142	
   143	        for (String plan : Arrays.asList("STANDARD", "NON_REFUNDABLE")) {
   144	            BigDecimal amount = planAmounts.get(plan);
   145	            int count = planCounts.get(plan);
   146	
   147	            csv.append(plan).append(",")
   148	                .append(count).append(",")
   149	                .append(formatMoney(amount)).append("\n");
   150	
   151	            totalAmount = totalAmount.add(amount);
   152	            totalCount = totalCount + count;
