   128	
   129	        String status = reservation.getStatus();
   130	        if (!("PENDING".equals(status) || "CONFIRMED".equals(status))) {
   131	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only pending or confirmed reservations can be cancelled");
   132	        }
   133	
   134	        ReservationRepository.updateStatus(reservationId, "CANCELLED");
   135	
   136	        BigDecimal refund = BigDecimal.ZERO;
   137	        if ("CONFIRMED".equals(status)) {
   138	            if ("STANDARD".equals(reservation.getRatePlan())) {
   139	                refund = reservation.getAmountPaid();
   140	            }
   141	        }
   142	
   143	        if (refund.compareTo(BigDecimal.ZERO) > 0) {
   144	            ReservationRepository.updateRefund(reservationId, refund);
   145	        }
   146	
   147	        return ReservationRepository.findById(reservationId);
   148	    }
   149	}

