    39	        int day = date.getDayOfMonth();
    40	
    41	        if (month == 7) return true;
    42	
    43	        if (month == 12 && day >= 15) return true;
    44	
    45	        if (month >= 1 && month <= 2) return true;
    46	
    47	        return false;
    48	    }
