     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public class PriceCalculator {
     7	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
     8	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
     9	
    10	    public static class PriceResult {
    11	        public BigDecimal nightlyRate;
    12	        public BigDecimal subtotal;
    13	        public BigDecimal discount;
    14	        public BigDecimal total;
    15	
    16	        public PriceResult(BigDecimal nightlyRate, BigDecimal subtotal,
    17	                          BigDecimal discount, BigDecimal total) {
    18	            this.nightlyRate = nightlyRate;
    19	            this.subtotal = subtotal;
    20	            this.discount = discount;
    21	            this.total = total;
    22	        }
    23	    }
    24	
    25	    public static PriceResult calculate(BigDecimal baseRate, LocalDate checkIn,
    26	                                        LocalDate checkOut, String ratePlan) {
    27	        int nights = DateUtils.daysBetween(checkIn, checkOut);
    28	
    29	        BigDecimal nightlyRate = baseRate;
    30	        if (isHighSeasonForAny(checkIn, checkOut)) {
    31	            nightlyRate = baseRate.multiply(HIGH_SEASON_MULTIPLIER);
    32	        }
    33	        nightlyRate = MoneyRounder.round(nightlyRate);
    34	
    35	        BigDecimal subtotal = nightlyRate.multiply(new BigDecimal(nights));
    36	        subtotal = MoneyRounder.round(subtotal);
    37	
    38	        BigDecimal discount = BigDecimal.ZERO;
    39	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    40	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
    41	            discount = MoneyRounder.round(discount);
    42	        }
    43	
    44	        BigDecimal total = subtotal.subtract(discount);
    45	        total = MoneyRounder.round(total);
    46	
    47	        return new PriceResult(nightlyRate, subtotal, discount, total);
    48	    }
    49	
    50	    private static boolean isHighSeasonForAny(LocalDate checkIn, LocalDate checkOut) {
    51	        LocalDate current = checkIn;
    52	        while (current.isBefore(checkOut)) {
    53	            if (DateUtils.isHighSeason(current)) {
    54	                return true;
    55	            }
    56	            current = current.plusDays(1);
    57	        }
    58	        return false;
    59	    }
    60	}

