     7	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
     8	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
     9	
    10	    public static class PriceResult {
    11	        public BigDecimal nightlyRate;
    12	        public BigDecimal subtotal;
