    25	    public static PriceResult calculate(BigDecimal baseRate, LocalDate checkIn,
    26	                                        LocalDate checkOut, String ratePlan) {
    27	        int nights = DateUtils.daysBetween(checkIn, checkOut);
    28	
    29	        BigDecimal nightlyRate = baseRate;
    30	        if (isHighSeasonForAny(checkIn, checkOut)) {
    31	            nightlyRate = baseRate.multiply(HIGH_SEASON_MULTIPLIER);
    32	        }
    33	        nightlyRate = MoneyRounder.round(nightlyRate);
    34	
    35	        BigDecimal subtotal = nightlyRate.multiply(new BigDecimal(nights));
    36	        subtotal = MoneyRounder.round(subtotal);
    37	
    38	        BigDecimal discount = BigDecimal.ZERO;
    39	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    40	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
    41	            discount = MoneyRounder.round(discount);
    42	        }
    43	
    44	        BigDecimal total = subtotal.subtract(discount);
    45	        total = MoneyRounder.round(total);
    46	
    47	        return new PriceResult(nightlyRate, subtotal, discount, total);
    48	    }
