    50	    private static boolean isHighSeasonForAny(LocalDate checkIn, LocalDate checkOut) {
    51	        LocalDate current = checkIn;
    52	        while (current.isBefore(checkOut)) {
    53	            if (DateUtils.isHighSeason(current)) {
    54	                return true;
    55	            }
